1	//! Tests for Innistrad Tier 10 cards with activated abilities:
2	//! Manor Skeleton, Kessig Wolf, Feral Ridgewolf, Darkthicket Wolf,
3	//! Lantern Spirit, Avacynian Priest.
4	
5	mod common;
6	
7	use common::*;
8	use mtg_engine::actions::{Action, Target};
