15	    CardRegistry::with_all_cards()
16	}
17	
18	// ══════════════════════════════════════════════════════════════════
19	// Manor Skeleton — {1}{B} 1/1 Skeleton, Haste, {1}{B}: Regenerate
20	// ══════════════════════════════════════════════════════════════════
21	
22	#[test]
23	fn manor_skeleton_has_correct_stats() {
24	    let reg = registry();
25	    let id = reg.get_id_by_name("Manor Skeleton").unwrap();
26	    let data = reg.card_data(id).unwrap();
27	    assert_eq!(data.power, Some(1));
28	    assert_eq!(data.toughness, Some(1));
29	    assert!(data.keywords.contains(&Keyword::Haste));
30	    assert!(data.subtypes.contains(&"Skeleton".to_string()));
31	}
32	
33	#[test]
34	fn manor_skeleton_regenerate_ability() {
35	    let reg = registry();
36	    let mut state = game_at_step(Step::PrecombatMain, P0);
37	
38	    let skeleton = named_creature(&mut state, &reg, "Manor Skeleton", P0);
39	
40	    // Add mana to pay {1}{B} for regenerate.
41	    state.get_player_mut(P0).mana_pool.add(ManaType::Colorless, 1);
42	    state.get_player_mut(P0).mana_pool.add(ManaType::Black, 1);
43	
44	    let legal = engine::legal_actions(&state, &reg);
45	    let activate = legal.actions.iter().find(|a| matches!(a, Action::ActivateAbility { .. }));
46	    assert!(activate.is_some(), "Should be able to activate regenerate ability");
47	
48	    state = engine::submit_action(&state, activate.unwrap(), &reg);
49	    assert_eq!(state.get_object(skeleton).unwrap().regeneration_shields, 1,
50	        "Activating should add a regeneration shield");
51	}
52	
